replacements.after:
// Pin editor requests without changing the site's cache state.
$editor_version = '73dfed6073b8-backdrop-1';
$cache_buster = '?' . state_get('css_js_query_string', '') . '&h5p_editor=' . $editor_version;
$ui_language = $language->langcode === 'fr' ? 'fr' : 'en';

// CKEditor translations and compatibility belong inside the editor iframe.
if ($ui_language === 'fr') {
  $assets['js'][] = base_path() . $h5peditor_module_path . '/h5peditor/ckeditor/translations/fr.js' . $cache_buster;
}
$assets['js'][] = base_path() . $h5peditor_module_path . '/scripts/h5peditor-backdrop-compat.js' . $cache_buster;
$editor_js_options = array('preprocess' => FALSE, 'version' => $editor_version);
backdrop_add_js($h5peditor_module_path . '/h5peditor/scripts/h5peditor-editor.js', $editor_js_options);
backdrop_add_js($h5peditor_module_path . '/scripts/application.js', $editor_js_options);

h5peditor = new ns.Editor(library, $params.val(), $editor[0], function () {
  // This callback runs in the iframe before selectors and forms.
  this.H5PBackdropEditorCompatibility.installNestedLanguageUpdates(this.H5PEditor);
  this.H5PBackdropEditorCompatibility.installRichTextLanguage(this.H5PEditor);
});

function installRichTextLanguage(editor) {
  if (!editor || !editor.Html || !editor.Html.prototype ||
      typeof editor.Html.prototype.getCKEditorConfig !== 'function') {
    throw new Error('Load the H5P HTML widget before installing rich-text language compatibility.');
  }
  var prototype = editor.Html.prototype;
  var original = prototype.getCKEditorConfig;
  if (original.backdropRichTextLanguageAdapter === true) {
    return false;
  }
  function getConfig() {
    var config = original.call(this);
    config.language = {
      ui: editor.uiLanguage === 'fr' ? 'fr' : 'en',
      content: editor.defaultLanguage || editor.contentLanguage || 'en'
    };
    return config;
  }
  getConfig.backdropRichTextLanguageAdapter = true;
  prototype.getCKEditorConfig = getConfig;
  return true;
}

var compatibility = {
  installNestedLanguageUpdates: installNestedLanguageUpdates,
  installRichTextLanguage: installRichTextLanguage
};
